using System;using System.IO;using System.Linq;using System.Collections.Generic;using Frociart;
public static class FpgtTypesTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 static FlowFpgtTypes Analyze(string text){return new FlowFpgtTypes(FlowSource.Compile(FlowPseudocode.Decode(text)));}
 public static int Main(string[] args){try{
  var a=Analyze("x=1\ny=x/2\ns=\"x\" & x\nok=y>0");var scope=a.Find(null);Check(scope.Find("x").Type.Kind==1&&scope.Find("y").Type.Kind==2&&scope.Find("s").Type.Kind==3&&scope.Find("ok").Type.Kind==4,"Nominal scalar facts across assignments");Check(a.Issues.Count==0,"Stable implicit variables do not require a profile");
  var fixedType=Analyze("DICHIARA x: INTERO\nx=3.5\nSTAMPA x");Check(fixedType.Find(null).Find("x").Type.Kind==1&&fixedType.Find(null).Find("x").Declared,"Declared type takes precedence over assignment value");
  var mixed=Analyze("x=1\nx=\"one\"\nSTAMPA x");Check(mixed.Issues.Any(i=>i.Code=="changing-type"&&i.NodeId!=null),"Changing nominal types have a linked diagnostic");
  var d=FlowPseudocode.Decode("LEGGI x\nSTAMPA x");byte[] before=DiagramIO.EncodeDocument(d);var p=FlowSource.Compile(d);var unknown=new FlowFpgtTypes(p);Check(unknown.Issues.Any(i=>i.Code=="input-type")&&unknown.Find(null).Find("x").InputChoice,"Dynamic input requires a deliberate generated type");var chosen=new FlowFpgtTypes(p,new Dictionary<string,FlowDataType>{{FlowFpgtTypes.Key(null,"X"),FlowDataType.Real}});Check(chosen.Find(null).Find("x").Type.Kind==2&&!chosen.Find(null).Find("x").InputChoice&&chosen.Issues.Count==0,"Profile resolves only the generated copy");Check(before.SequenceEqual(DiagramIO.EncodeDocument(d)),"Type inference and profile preserve original document bytes");
  var declared=Analyze("DICHIARA x: REALE\nLEGGI x\nSTAMPA x");Check(!declared.Find(null).Find("x").InputChoice&&declared.Issues.Count==0,"Declared input needs no repeated choice");
  var vector=Analyze("DICHIARA a: INTERO[3]\na[0]=4\nb=a[0]+1\nSTAMPA b");Check(vector.Find(null).Find("a").Type.Array&&vector.Find(null).Find("a").Type.Kind==1&&vector.Find(null).Find("a").LiteralLength==3&&vector.Find(null).Find("b").Type.Kind==1,"Array element and constant-size facts");
  var funcs=Analyze("FUNZIONE f(a: RIF INTERO[]) -> INTERO r\nr=a[0]\nFINE FUNZIONE\nDICHIARA v: INTERO[2]\nx=f(v)\nSTAMPA x");var f=funcs.Scopes.Single(s=>s.Source.Id!=null);Check(f.Find("a").Parameter&&f.Find("a").Reference&&f.Find("a").Type.Array&&f.ReturnType.Kind==1&&funcs.Find(null).Find("x").Type.Kind==1,"Parameters, references and function result facts");
  var intrinsic=Analyze("x=floor(1.5)\ny=tofixed(1.5,2)\nz=EOF()");Check(intrinsic.Find(null).Find("x").Type.Kind==1&&intrinsic.Find(null).Find("y").Type.Kind==3&&intrinsic.Find(null).Find("z").Type.Kind==4,"Intrinsic types inferred without reading a file or calling EOF");
  var pi=Analyze("STAMPA pi");Check(pi.Find(null).Find("pi").ConstantPi&&pi.Find(null).Find("pi").Type.Kind==2,"Pi constant remains distinguished from variables");
  var shadow=Analyze("STAMPA pi\npi=3\nSTAMPA pi");Check(!shadow.Find(null).Find("pi").ConstantPi&&shadow.Find(null).Find("pi").Type.Kind==2,"A mutable pi retains a real type for its initial constant value");
  var indexedInput=FlowSource.Compile(FlowPseudocode.Decode("v=[0,0]\nLEGGI v[0]\nSTAMPA v[0]"));var vectorChoice=new FlowFpgtTypes(indexedInput,new Dictionary<string,FlowDataType>{{FlowFpgtTypes.Key(null,"v"),FlowDataType.Real}});Check(vectorChoice.Find(null).Find("v").Type.Array&&vectorChoice.Find(null).Find("v").Type.Kind==2,"A generated input choice preserves vector shape");
  int accepted=0;foreach(string file in Directory.GetFiles(Path.Combine(args[0],"../expression-compat-qa/fixtures"),"*.frociart")){var doc=DiagramIO.DecodeDocument(File.ReadAllBytes(file));var program=FlowSource.Compile(doc);if(!program.CanGenerate)continue;byte[] bytes=DiagramIO.EncodeDocument(doc);var facts=new FlowFpgtTypes(program);Check(bytes.SequenceEqual(DiagramIO.EncodeDocument(doc)),"Corpus analysis is passive");Check(facts.Scopes.Count==program.Scopes.Count,"Corpus retains every scope");accepted++;}
  Console.WriteLine("FPGT_TYPES_CSHARP PASS checks="+checks+" corpus="+accepted);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
